import {
  installNativeTransport,
  NativeBridgeError,
  validateNativeHostInfo,
  type EventSubscription,
  type NativeHostInfo,
  type NativeTransport,
} from "./nativeBridge.ts";

/** Shapes generated by bay.mojom.NativeHost, without importing Mojo into shared code. */
export interface MojoNativeHostRemote {
  getHostInfo(): Promise<{ infoJson: string }>;
  invoke(module: string, method: string, argsJson: string): Promise<{ resultJson: string }>;
  setClient(client: unknown): void;
  $?: { close?(): void };
}
type RouterEvent<Args extends unknown[]> = { addListener(listener: (...args: Args) => void): number };
export interface MojoNativeHostClientRouter {
  onNativeEvent: RouterEvent<[module: string, name: string, payloadJson: string]>;
  onHostInfoChanged: RouterEvent<[infoJson: string]>;
  removeListener(id: number): boolean | void;
  $: { bindNewPipeAndPassRemote(): unknown; close?(): void };
}
export type WebNativeBridgeOptions = {
  remote: MojoNativeHostRemote;
  client: MojoNativeHostClientRouter;
  onProtocolError?: (error: Error) => void;
  bootstrapTimeoutMs?: number;
};

const MAX_PENDING_NOTIFICATION_RESPONSES = 32;
const MAX_PENDING_NOTIFICATION_BYTES = 256 * 1024;

function awaitsWindowAssignment(info: NativeHostInfo): boolean {
  const shell = info.constants.BayShell;
  if (typeof shell?.initializationError === "string" && shell.initializationError) return false;
  return shell?.sharedRuntime === true && shell.runtimeRole === "window" && (shell.windowId === undefined || shell.windowId === "");
}

/** Only the trusted chrome://bay bootstrap creates the Mojo endpoints. No window messages are accepted. */
export async function createMojoTransport({
  remote,
  client,
  onProtocolError = (error) => console.error(error),
  bootstrapTimeoutMs = 15000,
}: WebNativeBridgeOptions): Promise<NativeTransport> {
  let info: NativeHostInfo | null = null;
  let failure: Error | null = null;
  let disposed = false;
  let bootstrapUpdated: (() => void) | undefined;
  const listeners = new Map<string, Map<string, Set<{ listener: (payload: unknown) => void }>>>();
  const notificationResponses: { payload: unknown; bytes: number }[] = [];
  let notificationBytes = 0;
  let notificationDrainScheduled = false;
  let drainingNotifications = false;
  const encoder = new TextEncoder();
  const removers: number[] = [];
  const notificationListeners = () => listeners.get("BayApp")?.get("onNotificationResponse");
  const scheduleNotificationDrain = () => {
    if (disposed || failure || notificationDrainScheduled || drainingNotifications || !notificationResponses.length || !notificationListeners()?.size) return;
    notificationDrainScheduled = true;
    queueMicrotask(() => {
      notificationDrainScheduled = false;
      if (disposed || failure) return;
      drainingNotifications = true;
      try {
        // Events arriving during delivery join the next batch, after retained events.
        const count = notificationResponses.length;
        for (let i = 0; i < count && notificationResponses.length; i++) {
          const callbacks = [...(notificationListeners() ?? [])];
          if (!callbacks.length) break;
          const response = notificationResponses.shift()!;
          notificationBytes -= response.bytes;
          for (const subscription of callbacks) {
            try {
              subscription.listener(response.payload);
            } catch (error) {
              onProtocolError(error instanceof Error ? error : new Error(String(error)));
            }
          }
        }
      } finally {
        drainingNotifications = false;
        scheduleNotificationDrain();
      }
    });
  };
  const retainNotification = (json: string, payload: unknown) => {
    // UTF-8 is never shorter than its UTF-16 code unit count. Check length first
    // to avoid allocating an encoded copy of an oversized activation.
    if (json.length > MAX_PENDING_NOTIFICATION_BYTES) return;
    const bytes = encoder.encode(json).byteLength;
    if (bytes > MAX_PENDING_NOTIFICATION_BYTES) return;
    while (notificationResponses.length >= MAX_PENDING_NOTIFICATION_RESPONSES || notificationBytes + bytes > MAX_PENDING_NOTIFICATION_BYTES) {
      notificationBytes -= notificationResponses.shift()!.bytes;
    }
    notificationResponses.push({ payload, bytes });
    notificationBytes += bytes;
    scheduleNotificationDrain();
  };
  const parseInfo = (json: string): NativeHostInfo => {
    const parsed: unknown = JSON.parse(json);
    validateNativeHostInfo(parsed);
    return parsed;
  };
  const active = () => {
    if (disposed) throw new NativeBridgeError("transport_closed", "Bay's native transport is closed");
    if (failure) throw failure;
  };
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    for (const id of removers) client.removeListener(id);
    listeners.clear();
    notificationResponses.length = 0;
    notificationBytes = 0;
    client.$.close?.();
    remote.$?.close?.();
  };
  try {
    removers.push(
      client.onHostInfoChanged.addListener((json) => {
        if (disposed) return;
        try {
          info = parseInfo(json);
        } catch (error) {
          failure = error instanceof Error ? error : new Error(String(error));
          onProtocolError(failure);
        }
        const updated = bootstrapUpdated;
        bootstrapUpdated = undefined;
        updated?.();
      }),
    );
    removers.push(
      client.onNativeEvent.addListener((module, event, json) => {
        if (disposed || failure) return;
        let payload: unknown;
        try {
          payload = JSON.parse(json);
        } catch {
          onProtocolError(new NativeBridgeError("invalid_event", `Invalid native event JSON for ${module}.${event}`));
          return;
        }
        if (
          module === "BayApp" &&
          event === "onNotificationResponse" &&
          (!notificationListeners()?.size || notificationResponses.length || notificationDrainScheduled || drainingNotifications)
        ) {
          retainNotification(json, payload);
          return;
        }
        // oxlint-disable-next-line unicorn/no-useless-spread -- Snapshot subscribers so changes during delivery affect the next event.
        for (const subscription of [...(listeners.get(module)?.get(event) ?? [])]) subscription.listener(payload);
      }),
    );
    remote.setClient(client.$.bindNewPipeAndPassRemote());
    let timeout: ReturnType<typeof setTimeout> | undefined;
    try {
      const deadline = new Promise<never>((_, reject) => {
        timeout = setTimeout(() => reject(new NativeBridgeError("bootstrap_timeout", "Bay's native host did not finish starting")), bootstrapTimeoutMs);
      });
      const response = await Promise.race([remote.getHostInfo(), deadline]);
      const initial = parseInfo(response.infoJson);
      active();
      // An update received during bootstrap is newer than the initial snapshot.
      info ??= initial;
      // The coordinator restores canonical window IDs asynchronously. Keep
      // its initial shell pending until native reconciliation assigns one.
      while (awaitsWindowAssignment(info)) {
        await Promise.race([new Promise<void>((resolve) => (bootstrapUpdated = resolve)), deadline]);
        active();
      }
    } finally {
      clearTimeout(timeout);
      bootstrapUpdated = undefined;
    }
    return {
      getHostInfo() {
        active();
        return info!;
      },
      async invoke(module, method, argsJson) {
        active();
        const result = await remote.invoke(module, method, argsJson);
        active();
        return result.resultJson;
      },
      subscribe(module, event, listener) {
        active();
        let events = listeners.get(module);
        if (!events) listeners.set(module, (events = new Map()));
        let callbacks = events.get(event);
        if (!callbacks) events.set(event, (callbacks = new Set()));
        const entry = { listener };
        callbacks.add(entry);
        if (module === "BayApp" && event === "onNotificationResponse") scheduleNotificationDrain();
        let removed = false;
        return {
          remove() {
            if (removed) return;
            removed = true;
            callbacks.delete(entry);
            if (!callbacks.size) events.delete(event);
            if (!events.size) listeners.delete(module);
          },
        };
      },
      dispose,
    };
  } catch (error) {
    dispose();
    throw error;
  }
}

/** Await before dynamically importing nativeApi/main, whose native facades bind during module evaluation. */
export async function initializeWebNativeBridge(options: WebNativeBridgeOptions): Promise<EventSubscription> {
  const transport = await createMojoTransport(options);
  try {
    return installNativeTransport(transport);
  } catch (error) {
    transport.dispose?.();
    throw error;
  }
}
